"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["32457"],{15182(e){e.exports=JSON.parse('{"id":"FIN-1041","slug":"management-accounts","term":"Management Accounts","also_known_as":[],"difficulty":"Advanced","definition":"Management accounts are internal financial reports prepared for a business\'s managers, usually monthly, to help them monitor performance and make decisions.","explanation":["Unlike statutory accounts, management accounts have no required format and are not published. They are designed around what managers need, such as results by product, region or department, comparisons with budget and last year, cash forecasts and key performance indicators.","For example, a restaurant group might produce monthly management accounts showing sales, food costs, staff costs and profit for each restaurant, compared with budget, so managers can spot problems quickly.","Because speed matters more than perfect precision, management accounts may use estimates and simplified methods. They often include non-financial measures, such as customer numbers or staff turnover, and commentary explaining the main movements.","Management accounts are the core output of management accounting, which focuses on planning, control and decision-making rather than external reporting. Lenders and investors in private companies sometimes ask to see them, because they give a more timely picture than annual statutory accounts."],"note":"","total":1500,"prev":{"slug":"managed-float","term":"Managed Float"},"next":{"slug":"management-buyout","term":"Management Buyout (MBO)"}}')}}]);